            else: p['pos']+= dc
            ph.append(cell(p))
        return ph
    def state(t):
        ps=[dict(x) for x in P]
        for _ in range(t):
            for p in ps: step(p)
        return ps
    def traj(t):
        ps=[dict(x) for x in P]
        for _ in range(t):
            for p in ps: step(p)
        out=[]
        for p in ps:
            q=dict(p); ph=step(q); out.append((cell(p),cell(q),ph))
        return out
    return state,traj
